    @classmethod
    def from_prompt_execution_settings(
        cls, config: "PromptExecutionSettings"
    ) -> "MistralAIChatPromptExecutionSettings":
        """Create an instance of this class from a PromptExecutionSettings object.

        The service_id is copied over and any recognized fields are read from the
        extension_data of the passed in settings.

        Args:
            config: The PromptExecutionSettings object to copy from.

        Returns:
