            self.service_id = config.service_id
        for field in ("temperature", "top_p", "max_tokens", "messages"):
            value = getattr(config, field, None)
            if value is not None:
                setattr(self, field, value)

    def prepare_settings_dict(self, **kwargs: Any) -> dict[str, Any]:
        """Prepare the settings as a dictionary for sending to the AI service.

        Returns:
            A dictionary containing the temperature, top_p and max_tokens.
        """
        return {
            "temperature": self.temperature,
            "top_p": self.top_p,
            "max_tokens": self.max_tokens,
        }
